  if (nrhs > 1) {
    OP_REQUIRES_OK_ASYNC(
        context, DoMatrixTranspose(device, transposed_rhs, output), done);
  } else {
    device.memcpy(output->flat<Scalar>().data(),
                  transposed_rhs.flat<Scalar>().data(),
                  transposed_rhs.NumElements() * sizeof(Scalar));
