                          errors::InvalidArgument(kErrMsg), done);
      }
    }
    OP_REQUIRES_OK_ASYNC(context, status, done);
    done();
  };
  CudaSolver::CheckLapackInfoAndDeleteSolverAsync(std::move(solver), dev_info,
                                                  std::move(info_checker));
}

